$$
\mathcal {L} _ {\mathrm{KD}} = \tau^ {2} \cdot \mathrm{KL} \left(\sigma (\mathbf {z} ^ {S} / \tau) \| \sigma (\mathbf {z} ^ {T} / \tau)\right)\tag{1}
$$

$$
\mathbf {z} _ {i} ^ {T} = \alpha \mathbf {z} ^ {T} + (1 - \alpha) \mathbf {p} _ {i}\tag{2}
$$

$$
\mathbf {p} _ {0} = \mathcal {G} (\mathbf {f} ^ {S}; \theta_ {G}) = \mathbf {W} _ {2} \cdot \mathrm{Dropout} (\mathbf {W} _ {1} \mathbf {f} ^ {S} + \mathbf {b} _ {1}) + \mathbf {b} _ {2}\tag{3}
$$

$$
\mathbf {p} _ {i} = \text { CyclicShift } (\mathbf {p} _ {0}, \delta_ {i}), \quad \delta_ {i} = i \cdot \Delta , \quad \Delta = \lfloor C / N \rfloor\tag{4}
$$

$$
\operatorname{CyclicShift} (\mathbf {v}, \delta) = \left[ v _ {k + 1}, \dots , v _ {C}, v _ {1}, \dots , v _ {k} \right] ^ {\top}, \quad k = C - \delta\tag{5}
$$

$$
\mathcal {L} _ {\text { align }} = \sum_ {i = 1} ^ {N} \mathrm{KL} \left(\sigma (\mathbf {p} _ {i} / \tau) \| \sigma (\mathbf {z} ^ {T} / \tau)\right)\tag{6}
$$

$$
\mathcal {L} _ {\mathrm{div}} = \frac {1}{N (N - 1)} \sum_ {i = 1} ^ {N} \sum_ {j \neq i} \frac {\left\langle \mathbf {p} _ {i} , \mathbf {p} _ {j} \right\rangle}{\| \mathbf {p} _ {i} \| \| \mathbf {p} _ {j} \|}\tag{7}
$$

$$
\mathcal {L} _ {\mathrm{VD}} = \frac {1}{N} \sum_ {i = 1} ^ {N} \tau^ {2} \cdot \mathrm{KL} \left(\sigma (\mathbf {z} ^ {S} / \tau) \| \sigma (\mathbf {z} _ {i} ^ {T} / \tau)\right)\tag{8}
$$

$$
\mathcal {L} _ {\text { total }} = \mathcal {L} _ {\mathrm{KD}} + \lambda_ {1} \mathcal {L} _ {\mathrm{VD}} + \lambda_ {2} \mathcal {L} _ {\text { align }} + \lambda_ {3} \mathcal {L} _ {\text { div }}\tag{9}
$$

$$
\frac {\partial \mathcal {L} _ {\text { align }}}{\partial \theta_ {S}} = \frac {\partial \mathcal {L} _ {\text { align }}}{\partial \mathbf {p}} \frac {\partial \mathbf {p}}{\partial \mathbf {f} ^ {S}} \frac {\partial \mathbf {f} ^ {S}}{\partial \theta_ {S}}, \quad \frac {\partial \mathcal {L} _ {\text { div }}}{\partial \theta_ {S}} = \frac {\partial \mathcal {L} _ {\text { div }}}{\partial \mathbf {p}} \frac {\partial \mathbf {p}}{\partial \mathbf {f} ^ {S}} \frac {\partial \mathbf {f} ^ {S}}{\partial \theta_ {S}}\tag{10}
$$

